                "userinfo": 1,
                "tag": 1,
                "orderlist": 1,
                "song_begin": 0,
                "song_num": 1000 || item.songnum,
                "onlysonglist": 0,
                "enc_host_uin": ""
            }
        }
    });

    resp = zzcSignPost(data);
    songs = resp.req_0.data.songlist;

    tracks = songs.map(song => ({
        id: song.id,
        name: song.name,
        singer: song.singer.map(singer => singer.name).join(' '),
        time: song.time_public,
        isVip: song.pay.pay_play,
        subtitle: song.subtitle
    }));
    java.put("tracks", JSON.stringify(tracks));
    item = resp.req_0.data.dirinfo;

    intr = `&nbsp;💿 歌单：${item.title}\n👤 作者：${item.creator.nick}\n🏷️ 标签：${item.tag.map(tag => tag.name).join('，')}\n📜 列表：${item.songnum}首歌\n⏰ 时间：${java.timeFormat(item.mtime * 1000).slice(0, 10)}\n🎧 播放：${item.listennum}\n❤️ 收藏：${item.ordernum}\n📋 简介：${item.desc ? item.desc : "还没有简介※=○☆(＿＿*)Ｚｚｚ"}`;
    result = JSON.stringify({
        name: item.title,
        singer: item.creator.nick,
        kind: item.tag.map(tag => tag.name).concat(`▶︎${n2s(item.listennum)}`, `❤${n2s(item.ordernum)}`),
        latest: java.timeFormat(item.mtime * 1000).slice(0, 10),
        intr: intr,
        cover: item.picurl
    })
}

//toplist
else if (info.type == "toplist") {
    item = info.item;

    url = `https://i.y.qq.com/n2/m/share/details/toplist.html?ADTAG=myqq&from=myqq&channel=10007100&id=${item.topId}`;
