    tracks = songs.map(song => ({
        id: song.id,
        name: song.name,
        singer: song.singer.map(singer => singer.name).join(' '),
        time: song.time_public,
        isVip: song.pay.pay_play,
        subtitle: song.subtitle
    }));
    java.put("tracks", JSON.stringify(tracks));

    intr = `&nbsp;💿 歌单：${item.title}\n👤 作者：QQ音乐官方榜单\n📜 列表：${item.totalNum}首歌\n⏰ 时间：${item.updateTime}\n🎧 播放：${item.listenNum}\n📋 简介：${item.intro ? item.intro : "还没有简介※=○☆(＿＿*)Ｚｚｚ"}`;
    result = JSON.stringify({
        'name': item.title,
        'author': 'QQ音乐官方榜单',
        'kind': [item.updateTips].concat(`▶︎${n2s(item.listenNum)}`),
        'latest': item.updateTime,
        'intr': intr,
        'cover': item.frontPicUrl
    })
}

