@js:
type=java.get('type')

function $(text){
		return text!=""?true:false
	}
function J(url){
		return url.match(/guid/)?true:false
	}


function getUrl(){
if(type=='netease'){
		id = baseUrl.match(/\?id=(\d+)/)[1]
		ajaxUrl = `https://music.163.com/api/song/enhance/player/url?br=320000&ids=["${id}"]`
		try{
			url = JSON.parse(java.ajax(ajaxUrl)).data[0].url
		}catch (err){}
		return $(url)?url:`http://music.163.com/song/media/outer/url?id=${id}.mp3`
	}
else if(type=='qq'){
		i=0
		base=baseUrl.replace(/&code=.+/,'')
		code=["192aac","128mp3","flac"]
		return getUrl1()
	}
}


function getUrl1(){
		ajaxUrl(code[i])
		if(J(url)){
				return url
			}
		else{
				i++
				return i<3?getUrl1():''
			}
	}

function ajaxUrl(code){
	try{
		ajax = java.ajax(base+'&code=size_'+code)
		return url=JSON.parse(ajax).data.url
	}
	catch (e){
		return url=''
	}
}


i=0
if(type=='migu'){
url=baseUrl.replace(/^.*\?wd=/,'')
	}
else{
url=java.getString('$..url||$..play_url||$..play_backup_url||$..hqurl||$..lqurl')
	}

if(type=='qq'){
		url=J(url)?url:getUrl()
	}
else{
		url=$(url)?url:getUrl()
	}
$(url)?url:java.toast('没有链接')

